-- Speglar det som lades på databasen 2026-09-16 via apply_migration i fem delar:
--   sv1000_order_code_from_catalogue_part_01  (backup, schema, familj, parametrar)
--   sv1000_order_code_from_catalogue_part_02  (värdelista, rensning av regler)
--   sv1000_order_code_from_catalogue_part_03  (regler 1–20)
--   sv1000_order_code_from_catalogue_part_04  (regler 21–60)
--   sv1000_order_code_from_catalogue_part_05  (regler 61–68, dokumentkarta, produktraden döpt om)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts sv1000):
--   regler  68   md5 97f173c30971b6dc8b6ec2f04e413a05   villkor edb22d13fd27c7f14d9ef3f5b50b96f6
--   värden  90   md5 026a90ff952ecabbbc0b144e4292a3ff
--   schema       md5 16677c058f69d01f9040791da9ac5cec
-- Verifierat live: /sv/configurator/sv1000 bygger SS5V1-W10S1NAND-05U-C6 (nyckelns exempel sida 58),
-- stoppar DIN-skena utan SI-enhet (not 1) och varnar för specificerad layout över 8 stationer med
-- 16 utgångar (not 2).
--
-- SV: rampens beställnyckel enligt SMC 5 Port Solenoid Valve SV1000/2000/3000/4000 Series (EX260, sida 58).
-- GENERERAD ur src/lib/catalog/sv.ts -- redigera inte för hand.
--
-- Rättar familjen sv1000, som hade mallen 'SV1000-{stations}-{fieldbus}-{voltage}'
-- med påhittade värden. SMC:s kod för EX260-basen är
-- SS5V{serie}-W10S1{SI-enhet}D-{stationer}{P/E-läge}{SUP/EXH}-{montering}-{port},
-- t.ex. SS5V1-W10S1NAND-05U-C6 (nyckelns exempel sida 58). Serierna SV2000/3000,
-- de trettio SI-enheterna med artikelnummer, stationsgränserna, SUP/EXH-blocket,
-- DIN-monteringen och portarna fanns inte alls. EX500/EX250-ramperna utgår
-- (sida 19); EX600, EX126, EX120, rundkontakt, D-sub, flatkabel och kassettbasen
-- är egna nycklar.
--
-- SMC-SS5V1-W10S1-04 döps om till SMC-SS5V1-W10S10D-04U-C6.

begin;

create schema if not exists backup;
create table if not exists backup.sv1000_before_20260916 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'sv1000'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'sv1000'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'sv1000';

