on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  title = 'Ventilramp SV1000/2000/3000 med seriell enhet EX260 (IP67) — basen; ventilerna beställs per station',
  description = 'SMC SV1000/2000/3000 tie-rod manifold base for the EX260 serial transmission system (IP67): 2–20 stations, SI unit by protocol (DeviceNet, PROFIBUS DP, CC-Link, EtherCAT, PROFINET, EtherNet/IP, POWERLINK) with 32 or 16 outputs, P/E port location, SUP/EXH block, DIN rail mounting and One-touch port sizes. The valves SV□□00-5□□ are ordered per station.',
  stroke_min_mm = null,
  stroke_max_mm = null,
  order_code_template = 'SS5V{series}-W10S1{si}D-{stations}{pe}{supexh}-{mounting}-{port}',
  rules_schema_id = 'SCHEMA-SV1000-V1'
where slug = 'sv1000';


delete from configurator_param_values v using configurator_params p, configurator_families f
