insert into knowledge_doc_families (source_file, family_slug, doc_title)
values ('smc-kat-sv1000.pdf', 'sv1000', 'SMC — SMC 5 Port Solenoid Valve SV1000/2000/3000/4000 Series')
on conflict (source_file, family_slug) do update set doc_title = excluded.doc_title;


update products set
  sku = 'SMC-SS5V1-W10S10D-04U-C6',
  name = 'SV1000 ventilramp 4 stationer, EX260-bas utan SI-enhet, ø6',
  description = 'SV1000 tie-rod manifold base for the EX260 serial system (IP67), 4 stations, without SI unit (add the SI unit by symbol, e.g. NAN for PROFIBUS DP), P/E ports on the U side (ø8), A/B ports ø6 One-touch, internal pilot, direct mounting. Valves SV1100-5FU etc. are ordered per station. Order code SS5V1-W10S10D-04U-C6 (catalogue page 58).'
where sku = 'SMC-SS5V1-W10S1-04';

update product_specs s set value = 'A/B ø6 snabbkoppling, P/E ø8 snabbkoppling'
from products p where s.product_id = p.id and p.sku = 'SMC-SS5V1-W10S10D-04U-C6' and s.key = 'port_size';

insert into product_specs (product_id, key, value)
select p.id, x.key, x.value
from products p
cross join lateral (values
  ('series', 'SV1000'),
  ('si_unit', 'Utan (0); EX260-enheter per symbol, sida 58'),
  ('max_pressure', '7'),
  ('min_pressure_mpa', '0.15 (dubbel 0.1, 3-läges 0.2)'),
  ('temp_range', '-10 to +50'),
  ('ip_rating', 'IP67'),
  ('power_w', '0.6 per ventil'),
  ('order_code_example', 'SS5V1-W10S10D-04U-C6'),
  ('catalogue', 'SMC SV1000/2000/3000/4000, How to Order Manifold (EX260) sida 58, ventilerna sida 59, data sida 27')
) as x(key, value)
where p.sku = 'SMC-SS5V1-W10S10D-04U-C6'
  and not exists (select 1 from product_specs y where y.product_id = p.id and y.key = x.key);


commit;

